  1491  UA_decodeBinaryInternal(void *dst, const UA_DataType *type) {
  1492      uintptr_t ptr = (uintptr_t)dst;
  1493      status ret = UA_STATUSCODE_GOOD;
  1494      u8 membersSize = type->membersSize;
  1495      const UA_DataType *typelists[2] = { UA_TYPES, &type[-type->typeIndex] };
  1496      for(size_t i = 0; i < membersSize && ret == UA_STATUSCODE_GOOD; ++i) {
  1497          const UA_DataTypeMember *member = &type->members[i];
  1498          const UA_DataType *membertype = &typelists[!member->namespaceZero][member->memberTypeIndex];
  1499          if(!member->isArray) {
  1500              ptr += member->padding;
  1501              size_t fi = membertype->builtin ? membertype->typeIndex : UA_BUILTIN_TYPES_COUNT;
  1502              size_t memSize = membertype->memSize;
  1503              ret |= decodeBinaryJumpTable[fi]((void *UA_RESTRICT)ptr, membertype);
  1504              ptr += memSize;
  1505          } else {
  1506              ptr += member->padding;
  1507              size_t *length = (size_t*)ptr;
  1508              ptr += sizeof(size_t);
  1509              ret |= Array_decodeBinary((void *UA_RESTRICT *UA_RESTRICT)ptr, length, membertype);
  1510              ptr += sizeof(void*);
  1511          }
  1512      }
  1513      return ret;
